const repository = {
  id: "application",
  name: "Application repository",
  type: "function",
  list: (query, context) =&gt; templateApi.list(query),
  get: (id, context) =&gt; templateApi.get(id),
  save: (record, context) =&gt; templateApi.save(record)
};

translations.api.code.1:
await studio.listTemplates({
  search: "invoice",
  status: "published",
  tags: ["sales"],
  repositoryId: "company-api"
});

const record = await studio.getTemplateRecord("invoice-en", {
  repositoryId: "company-api"
});
await studio.loadTemplate(record);
await studio.saveTemplateRecord(
  { name: "Invoice", tags: ["sales"], status: "draft" },
  { repositoryId: "company-api" }
);

